  const downloadSelected = async () => { if (!selectedIds.length) return toast.error("Wählen Sie mindestens einen Lead aus."); const csv = await exportSelected.mutateAsync({ publicIds: selectedIds }); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "fluxora-lead-auswahl.csv"; anchor.click(); URL.revokeObjectURL(url); };
  const executeStagedAction = () => { if (!selectedIds.length || !stagedAction) return toast.error("Wähle zuerst eine Aktion aus."); if (["buyer", "supplier", "automation", "chain", "order"].includes(stagedAction) && !Number(stagedTargetId)) return toast.error("Wähle zuerst ein Ziel für die Aktion aus."); if (stagedAction === "buyer") assignMember.mutate({ publicIds: selectedIds, userId: Number(stagedTargetId) }); if (stagedAction === "supplier") assignSupplier.mutate({ publicIds: selectedIds, supplierId: Number(stagedTargetId) }); if (stagedAction === "automation") assignAutomation.mutate({ publicIds: selectedIds, ruleId: Number(stagedTargetId) }); if (stagedAction === "chain") assignChain.mutate({ publicIds: selectedIds, chainId: Number(stagedTargetId) }); if (stagedAction === "order") assignOrder.mutate({ publicIds: selectedIds, orderId: Number(stagedTargetId) }); if (stagedAction === "deliver") selectedIds.forEach((publicId) => deliver.mutate({ publicId })); if (stagedAction === "duplicate") duplicateLeads.mutate({ publicIds: selectedIds }); if (stagedAction === "deactivate") deactivateLeads.mutate({ publicIds: selectedIds }); if (stagedAction === "export") void downloadSelected(); if (stagedAction === "delete") requestDelete(selectedIds); if (stagedAction !== "delete") { setStagedAction(""); setStagedTargetId(""); } };
