  const importCsvFile = prepareCsvImport;
  const downloadImportErrors = () => { if (!importReport?.errorRows.length) return; const sourceHeaders = importReport.headers; const escape = (value: string | number) => `"${String(value).replaceAll('"', '""')}"`; const rows = [ ["Fehlerzeile", "Fehler", ...sourceHeaders], ...importReport.errorRows.map((error) => [error.rowNumber, error.reason, ...sourceHeaders.map((header) => error.values[header] ?? "")]) ]; const csv = rows.map((row) => row.map(escape).join(";")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${importFileName.replace(/\.csv$/i, "") || "lead-import"}-fehler.csv`; anchor.click(); URL.revokeObjectURL(url); };
  const importPreparedCsv = async () => { const categoryId = Number(importCategoryId); const report = importReport; if (!categoryId || !report || !importFileName) return toast.error("Wähle Kategorie und CSV-Datei aus."); if (!report.rows.length) return toast.error("In der Vorschau sind keine gültigen Lead-Zeilen vorhanden."); const batch = await startImportBatch.mutateAsync({ categoryId, fileName: importFileName, totalRows: report.rows.length + report.errorRows.length, errorDetails: report.errorRows }); const importedIds: string[] = []; setLastImportBatchId(batch.batchId); setIsImporting(true); setImportProgress({ completed: 0, total: report.rows.length }); try { for (let index = 0; index < report.rows.length; index += 1) { const row = report.rows[index]; const result = await create.mutateAsync({ categoryId, firstName: row.firstName, lastName: row.lastName, email: row.email, phone: row.phone, postcode: row.postcode, city: row.city, metadata: Object.keys(row.metadata).length ? row.metadata : undefined, country: "DE", cost: 0 }); if (result.publicId) importedIds.push(result.publicId); setImportProgress({ completed: index + 1, total: report.rows.length }); } await finishImportBatch.mutateAsync({ batchId: batch.batchId, leadPublicIds: importedIds, importedRows: importedIds.length, errorRows: report.errorRows.length }); setLastImportIds(importedIds); utils.leadops.listLeadImportBatches.invalidate(); toast.success(`${importedIds.length} Lead${importedIds.length === 1 ? "" : "s"} importiert.`); } catch (error) { await finishImportBatch.mutateAsync({ batchId: batch.batchId, leadPublicIds: importedIds, importedRows: importedIds.length, errorRows: report.errorRows.length + 1 }).catch(() => undefined); setLastImportIds(importedIds); utils.leadops.listLeadImportBatches.invalidate(); toast.error(error instanceof Error ? error.message : "Der Import wurde teilweise ausgeführt."); } finally { setIsImporting(false); setImportProgress(null); } };
